import{_ as a,o as l,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2023-06-28","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2023-06-28","date":"2023-06-28T00:00:00.000Z","updated":"2023-07-03T00:00:00.000Z","tags":["Ceph","RGW重构","异步请求","线程池优化","Neo","rados迁移"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-06-28.md","filePath":"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-06-28.md","lastUpdated":1780460162000}'),o={name:"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-06-28.md"};function r(s,e,n,d,h,p){return l(),i("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h4><p>本次会议主要讨论了Ceph RGW组件的Reef版本更新、异步请求重构、线程池优化以及从librados迁移到Neo-rados的计划。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>Reef版本更新</strong></p><ul><li>计划解决版本化对象一致性和多站点加密对象损坏问题，以避免功能退化。</li><li>版本化对象一致性问题由Corey Snyder负责处理，加密对象损坏问题由Marcus负责，并与Shel担心进行跟踪。</li></ul></li><li><p><strong>异步请求重构</strong></p><ul><li>合并了扩展异步处理路径的大型PR，计划引入回归测试以确保所有阻塞的librados调用都被发现并防止新增。</li><li>讨论了如何在编译时和运行时检查阻塞调用，特别是在Ezio线程中。</li></ul></li><li><p><strong>线程池优化</strong></p><ul><li>计划在消除所有阻塞调用后，大幅降低线程池大小，可能调整为核心数的一个小倍数。</li><li>讨论了性能测试以确定最佳线程池大小。</li></ul></li><li><p><strong>从librados迁移到Neo-rados</strong></p><ul><li>Jason Dillerman发现迁移到Neo-rados有显著性能提升，计划逐步转换，可能由Calpesh负责。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>解决版本化对象一致性和加密对象损坏问题。</li><li>引入回归测试，确保异步请求的非阻塞性。</li><li>进行线程池大小调整的性能测试。</li><li>逐步从librados迁移到Neo-rados。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>跟踪和解决版本化对象一致性问题。</li><li>与Marcus合作解决加密对象损坏问题。</li><li>实施回归测试。</li><li>进行线程池大小调整的性能测试。</li><li>开始从librados迁移到Neo-rados的工作。</li></ul><h4 id="其他讨论点" tabindex="-1">其他讨论点 <a class="header-anchor" href="#其他讨论点" aria-label="Permalink to &quot;其他讨论点&quot;">​</a></h4><ul><li>讨论了如何处理阻塞的后端存储，如SQLite，以及如何在未来可能完全移除null yield时保持系统的可扩展性。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><p>会议在讨论完所有议题后结束，感谢所有参与者的贡献。</p>',13)])])}const c=a(o,[["render",r]]);export{_ as __pageData,c as default};
